CREATE OR REPLACE FUNCTION public.static_weekly_approved_initial_materialize_projection(p_publication_id uuid, p_service_date date, p_exception_set_digest text, p_compiler_version text, p_objective jsonb, p_metrics jsonb, p_replay_digest text, p_assignments jsonb, p_expected_revision bigint, p_actor_manager_id uuid, p_actor_manager_name text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_request jsonb; v_request_digest text; v_prior public.weekly_schedule_command_receipts%rowtype; v_publication public.weekly_schedule_publications%rowtype; v_effective_start date; v_effective_end date; v_exception_set jsonb; v_exception_digest text; v_command uuid:=gen_random_uuid(); v_projection uuid:=gen_random_uuid(); v_revision bigint; v_content_digest text; v_response jsonb; v_item jsonb; v_assignment public.weekly_schedule_slot_assignments%rowtype; v_owner public.v_weekly_roster_slot_incumbency_ranges%rowtype; v_occurrence uuid; v_work jsonb;
begin
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_actor_manager_id,p_actor_manager_name,p_idempotency_key,'materialize_projection'); v_request:=jsonb_build_object('operation','materialize_projection','publication_id',p_publication_id,'service_date',p_service_date,'exception_set_digest',p_exception_set_digest,'compiler_version',p_compiler_version,'objective',p_objective,'metrics',p_metrics,'replay_digest',p_replay_digest,'projection_envelope',p_assignments,'expected_revision',p_expected_revision,'actor_manager_id',p_actor_manager_id,'actor_manager_name',p_actor_manager_name); v_request_digest:=public.static_weekly_digest_jsonb(v_request); perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts where actor_manager_id=p_actor_manager_id and idempotency_key=p_idempotency_key; if found then if v_prior.request_digest<>v_request_digest then raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs'; end if; return v_prior.response_json; end if;
  select * into v_publication from public.weekly_schedule_publications where publication_id=p_publication_id; select effective_start,effective_end into v_effective_start,v_effective_end from public.v_weekly_schedule_effective_ranges where version_id=v_publication.version_id; if not found or v_publication.publication_id is null or p_service_date is null or public.static_weekly_effective_version(p_service_date) is distinct from v_publication.version_id or mod(p_service_date-v_effective_start,7)<>0 or (v_effective_end is not null and p_service_date+6>=v_effective_end) then raise exception using errcode='23514',message='projection must be an aligned complete seven-day horizon wholly within one effective publication'; end if;
  v_exception_set:=public.static_weekly_accepted_exception_set(p_publication_id,p_service_date); v_exception_digest:=public.static_weekly_digest_jsonb(v_exception_set); if p_exception_set_digest is distinct from v_exception_digest or p_compiler_version is distinct from p_assignments->>'compiler_version' or p_objective is distinct from p_assignments->'objective' or p_metrics is distinct from p_assignments->'metrics' or p_replay_digest is distinct from p_assignments->>'replay_digest' then raise exception using errcode='23514',message='projection command identity must include exact compiler, objective, metrics, replay, and weekly exception authority'; end if;
  perform public.static_weekly_assert_approved_initial_projection(p_assignments,p_publication_id,p_service_date,v_exception_set); if exists(select 1 from public.weekly_schedule_compiled_projections where publication_id=p_publication_id and week_start=p_service_date and exception_set_digest=v_exception_digest and compiler_version=p_compiler_version and authority_digest=p_assignments->>'authority_digest') then raise exception using errcode='23505',message='immutable projection already exists for this exact weekly authority'; end if;
  v_content_digest:=public.static_weekly_digest_jsonb(jsonb_build_object('publication_id',p_publication_id,'week_start',p_service_date,'exception_set_digest',v_exception_digest,'compiler_version',p_compiler_version,'objective',p_objective,'metrics',p_metrics,'replay_digest',p_replay_digest,'projection_envelope_identity',p_assignments->>'database_projection_identity','attestation',p_assignments->'attestation')); v_revision:=public.static_weekly_advance_authority(p_expected_revision,'materialize_projection',p_actor_manager_id,p_actor_manager_name,v_command,v_content_digest);
  insert into public.weekly_schedule_compiled_projections(projection_id,publication_id,version_id,week_start,week_end,exception_set_json,exception_set_digest,compiler_version,objective_json,metrics_json,replay_digest,authority_digest,receipt_json,projection_envelope,compiled_by_manager_id) values(v_projection,p_publication_id,v_publication.version_id,p_service_date,p_service_date+6,v_exception_set,v_exception_digest,p_compiler_version,p_objective,p_metrics,p_replay_digest,p_assignments->>'authority_digest',p_assignments->'receipt',p_assignments,p_actor_manager_id);
  for v_item in select value from jsonb_array_elements(p_assignments->'assignments') loop
    v_owner:=null; v_assignment:=null; v_work:=v_item->'work_snapshot'; 
 if p_assignments#>>'{authority,schema}'='custodial.approved-static-authority.v1'
    and (v_work->>'overlayWork') is distinct from 'true' then
  select baseline.* into strict v_assignment
   from public.weekly_schedule_slot_assignments baseline
   join jsonb_array_elements(p_assignments#>'{authority,shiftEndDerivation,parentChains}') chain
    on baseline.work_id=chain->>'parentWorkId' and baseline.day_of_week=(chain->>'dayOfWeek')::smallint
   join lateral jsonb_array_elements(chain->'segments') segment on segment->>'workId'=v_item->>'work_id'
   where baseline.version_id=v_publication.version_id and baseline.day_of_week=(v_item->>'day_of_week')::smallint;
 else
  select * into v_assignment from public.weekly_schedule_slot_assignments
   where version_id=v_publication.version_id and day_of_week=(v_item->>'day_of_week')::smallint and work_id=v_item->>'work_id';
 end if;
  if v_assignment.assignment_id is null and (v_work->>'overlayWork') is distinct from 'true' then raise exception using errcode='23514',message='active baseline work must retain its stored baseline assignment link'; end if;
    perform public.static_weekly_capacity_assert_projection_owner(p_assignments,p_publication_id,v_item);
    if upper(v_item->>'status')='ASSIGNED' and v_item->>'owner_kind'='CONTRACTOR_CAPACITY' then
      v_owner:=null;
    elsif upper(v_item->>'status')='ASSIGNED' then select * into v_owner from public.v_weekly_roster_slot_incumbency_ranges where slot_id=(v_item->>'owner_slot_id')::uuid and effective_start<=(v_item->>'service_date')::date and (effective_end is null or (v_item->>'service_date')::date<effective_end); if not found or v_owner.person_id::text is distinct from v_item->>'owner_person_id' then raise exception using errcode='23514',message='projection assigned owner lacks an effective dated incumbent'; end if; elsif upper(v_item->>'status') not in ('OPEN','REVIEW') or v_item->>'owner_slot_id' is not null or v_item->>'owner_person_id' is not null then raise exception using errcode='23514',message='open and review projection rows must have null owner facts'; end if;
    insert into public.weekly_schedule_occurrences(projection_id,publication_id,version_id,assignment_id,service_date,work_id,day_of_week,location_id,location_code_snapshot,location_name_snapshot,coverage_start,coverage_end,owner_slot_id,owner_slot_label_snapshot,owner_person_id_snapshot,owner_name_snapshot,owner_kind,owner_capacity_id,state,state_reason,original_actor_person_id,original_actor_name_snapshot,authority_facts_json,occurrence_digest) values(v_projection,p_publication_id,v_publication.version_id,v_assignment.assignment_id,(v_item->>'service_date')::date,v_item->>'work_id',(v_item->>'day_of_week')::smallint,nullif(v_work->>'locationId','')::uuid,coalesce(v_work->>'locationCodeSnapshot',v_item->>'work_id'),coalesce(v_work->>'locationNameSnapshot',v_item->>'work_id'),(v_work#>>'{window,start}')::time,(v_work#>>'{window,end}')::time,case when lower(v_item->>'status')='assigned' then (v_item->>'owner_slot_id')::uuid else null end,case when lower(v_item->>'status')='assigned' then (select slot_label from public.weekly_roster_slots where slot_id=(v_item->>'owner_slot_id')::uuid) else null end,case when lower(v_item->>'status')='assigned' then (v_item->>'owner_person_id')::uuid else null end,case when lower(v_item->>'status')='assigned' then v_owner.person_name_snapshot else null end,nullif(v_item->>'owner_kind',''),nullif(v_item->>'capacity_id','')::uuid,case lower(v_item->>'status') when 'assigned' then 'created' when 'open' then 'open' else 'review' end,v_item->>'reason_code',nullif(v_item->>'original_actor_person_id','')::uuid,nullif(v_item->>'original_actor_name',''),jsonb_build_object('baseline_owner_slot_id',v_item->>'baseline_owner_slot_id','baseline_owner_person_id',v_item->>'baseline_owner_person_id','baseline_owner_name',v_item->>'baseline_owner_name','original_actor_person_id',v_item->>'original_actor_person_id','original_actor_name',v_item->>'original_actor_name','optimized_owner_slot_id',v_item->>'optimized_owner_slot_id','optimized_owner_person_id',v_item->>'optimized_owner_person_id','actual_actor_person_id',v_item->>'actual_actor_person_id','work_snapshot',v_work)||case when v_item->>'owner_kind'='CONTRACTOR_CAPACITY' then jsonb_build_object('owner_kind','CONTRACTOR_CAPACITY','capacity_id',v_item->>'capacity_id') else '{}'::jsonb end,public.static_weekly_digest_jsonb(v_item)) returning occurrence_id into v_occurrence;
    insert into public.weekly_schedule_projection_assignments(projection_id,occurrence_id,work_id,status,reason_code,owner_slot_id,owner_slot_label_snapshot,owner_person_id_snapshot,owner_name_snapshot,owner_kind,owner_capacity_id,authority_facts_json,explanation_json,content_digest) values(v_projection,v_occurrence,v_item->>'work_id',lower(v_item->>'status'),v_item->>'reason_code',case when lower(v_item->>'status')='assigned' then (v_item->>'owner_slot_id')::uuid else null end,case when lower(v_item->>'status')='assigned' then (select slot_label from public.weekly_roster_slots where slot_id=(v_item->>'owner_slot_id')::uuid) else null end,case when lower(v_item->>'status')='assigned' then (v_item->>'owner_person_id')::uuid else null end,case when lower(v_item->>'status')='assigned' then v_owner.person_name_snapshot else null end,nullif(v_item->>'owner_kind',''),nullif(v_item->>'capacity_id','')::uuid,(select authority_facts_json from public.weekly_schedule_occurrences where occurrence_id=v_occurrence),coalesce(v_item->'explanation','{}'::jsonb),public.static_weekly_digest_jsonb(v_item));
  end loop;
  v_response:=public.static_weekly_response_json('materialize_projection',v_revision,v_content_digest,v_request_digest,jsonb_build_object('projection_id',v_projection,'publication_id',p_publication_id,'week_start',p_service_date,'week_end',p_service_date+6,'replay_digest',p_replay_digest)); insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest) values(v_command,p_actor_manager_id,p_actor_manager_name,'materialize_projection',p_idempotency_key,p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest); return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_materialize_approved_initial_baseline(p_manager_id uuid, p_source_id uuid, p_date date, p_revision bigint, p_generation bigint, p_key text, p_envelope jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare actor jsonb;basis jsonb;baseline public.static_weekly_approved_initial_baselines%rowtype;prior public.static_weekly_approved_initial_confirmations%rowtype;
 document jsonb;projection jsonb;draft jsonb;published jsonb;materialized jsonb;lunch jsonb;receipt jsonb;provenance jsonb;
 v_version_id uuid;v_publication_id uuid;v_projection_id uuid;revision bigint;kind text;
begin
 perform public.static_weekly_v3_assert_control_plane();perform public.custodial_begin_application_mutation();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 actor:=public.static_weekly_v3_manager_actor(p_manager_id);
 if p_key is null or length(btrim(p_key)) not between 1 and 150 then raise exception 'exact initial idempotency key required';end if;
 select * into prior from public.static_weekly_approved_initial_confirmations where manager_id=p_manager_id and idempotency_key=p_key;
 if found then
  if prior.request_json is distinct from p_envelope->'request' then raise exception using errcode='23505',message='initial confirmation identity conflict';end if;
  return prior.receipt_json;end if;
 basis:=public.static_weekly_read_approved_initial_basis(p_manager_id,p_source_id,p_date,p_revision,p_envelope#>>'{request,templateId}');
 select * into strict baseline from public.static_weekly_approved_initial_baselines where source_id=p_source_id;
 if p_envelope->>'schema' is distinct from 'custodial.approved-static-initial-materialization.v1'
  or p_envelope->>'managerId' is distinct from p_manager_id::text or p_envelope->>'sourceId' is distinct from p_source_id::text
  or p_envelope->>'effectiveStart' is distinct from p_date::text or p_envelope->'expectedRevision' is distinct from to_jsonb(p_revision)
  or p_generation is distinct from (basis->>'generation')::bigint or p_envelope->'generation' is distinct from to_jsonb(p_generation)
  or p_envelope->>'templateCatalogDigest' is distinct from basis->>'templateCatalogDigest'
  or p_envelope->'feasibility' is distinct from baseline.feasibility
  or p_envelope->>'previewDigest' is distinct from public.static_weekly_digest_jsonb(p_envelope-'request'-'previewDigest')
  or p_envelope->'request' is distinct from jsonb_build_object('sourceId',p_source_id,'effectiveStart',p_date,
    'templateId',baseline.template_id,'expectedRevision',p_revision,'previewDigest',p_envelope->>'previewDigest','idempotencyKey',p_key) then
  raise exception using errcode='23514',message='initial baseline must bind exact current source/catalog/actor/revision/generation and independently prepared fixed snapshot';end if;
 document:=baseline.feasibility#>'{initialBaseline,document}';projection:=baseline.feasibility#>'{initialBaseline,projection}';
 provenance:=jsonb_build_object('adapter_schema',document#>>'{adapter,schema}','compiler_version',document#>>'{validation,compiler_version}',
  'input_digest',document#>>'{validation,input_digest}','baseline_input_digest',document#>>'{validation,baseline_input_digest}',
  'authority_digest',document#>>'{validation,authority_digest}','replay_digest',document#>>'{validation,replay_digest}');
 draft:=public.static_weekly_approved_initial_create_draft(p_date,projection->>'compiler_version',projection->'objective',provenance,
  document,p_revision,p_manager_id,actor->>'manager_name',p_key||':draft');
 v_version_id:=(draft#>>'{data,version_id}')::uuid;revision:=(draft->>'revision')::bigint;
 perform set_config('app.static_weekly_source_bind','on',true);
 update public.weekly_schedule_versions set authority_source_id=p_source_id where version_id=v_version_id and authority_source_id is null;
 if not exists(select 1 from public.weekly_schedule_versions v where v.version_id=v_version_id and v.authority_source_id=p_source_id) then raise exception 'initial source identity was not retained';end if;
 perform public.static_weekly_v3_assert_draft_incumbency(v_version_id);
 kind:=case when exists(select 1 from public.weekly_schedule_publications) then 'supersede' else 'publish' end;
 published:=public.static_weekly_approved_initial_publish_draft(v_version_id,(draft#>>'{data,draft_revision}')::bigint,revision,
  p_manager_id,actor->>'manager_name',p_key||':publish',kind,null);
 v_publication_id:=(published#>>'{data,publication_id}')::uuid;revision:=(published->>'revision')::bigint;
 materialized:=public.static_weekly_approved_initial_materialize_projection(v_publication_id,p_date,public.static_weekly_digest_jsonb('[]'::jsonb),
  projection->>'compiler_version',projection->'objective',projection->'metrics',projection->>'replay_digest',projection,revision,
  p_manager_id,actor->>'manager_name',p_key||':projection');
 v_projection_id:=(materialized#>>'{data,projection_id}')::uuid;revision:=(materialized->>'revision')::bigint;
 lunch:=public.static_weekly_v8_materialize_lunch_document(v_projection_id,baseline.feasibility->'lunchDocument',p_manager_id);
 if lunch->>'persistence_status' is distinct from 'PERSISTED' then raise exception 'initial lunch not persisted';end if;
 receipt:=jsonb_build_object('schema','custodial.approved-static-initial-confirmation.v1','status','PERSISTED_CURRENT',
  'ok',true,'persistence_status','PERSISTED','source_id',p_source_id,'publication_id',v_publication_id,'projection_id',v_projection_id,
  'authority_revision',revision,'revision',revision,'feasibility_digest',baseline.feasibility->>'digest',
  'lunch_document_identity',lunch->>'document_identity','previewDigest',p_envelope->>'previewDigest','solverInvoked',false);
 insert into public.static_weekly_approved_initial_confirmations values(p_manager_id,p_key,p_envelope->'request',receipt,v_publication_id,v_projection_id);
 return receipt;
end $function$
